import React, { useState } from 'react';
import { Calendar, ChevronDown, AlertCircle, User, MapPin, ListFilter, LayoutGrid, Download } from 'lucide-react';

const CollectionSchedule = () => {
  const [day, setDay] = useState('22');
  const [month, setMonth] = useState('MARCH');
  const [year, setYear] = useState('2026');
  const [viewMode, setViewMode] = useState('DAY');

  const scheduleLogs = [
    { id: 'SCH-1092', date: '22 MAR', time: '08:45', zone: 'NORTH_SEC', area: 'Hillside Drive', code: 'HSD-44', worker: 'RAVI_KUMAR', bins: '401, 405, 409', report: 'SENSOR_ERR' },
    { id: 'SCH-1104', date: '22 MAR', time: '13:20', zone: 'CENTRAL_HUB', area: 'Main Square', code: 'MSQ-01', worker: 'SITA_MAHESH', bins: '101, 102', report: null },
  ];

  return (
    <div className="w-full h-full flex flex-col gap-10 font-black italic uppercase tracking-tighter">

      {/* 🛠️ HEADER: THE SWITCH & SELECTORS */}
      <div className="flex flex-col lg:flex-row items-stretch gap-6">

        {/* VIEW SWITCHER */}
        <div className="flex bg-[#47510B] p-2 rounded-[25px] border-[4px] border-[#47510B] shadow-[6px_6px_0_0_#A1AED1]">
          <button 
            onClick={() => setViewMode('DAY')}
            className={`px-10 py-4 rounded-[20px] flex items-center gap-3 transition-all ${viewMode === 'DAY' ? 'bg-[#FFB6A9] text-[#47510B]' : 'text-white/40 hover:text-white'}`}
          >
            <Calendar size={24} /> <span className="text-xl">DAILY</span>
          </button>
          <button 
            onClick={() => setViewMode('MONTH')}
            className={`px-10 py-4 rounded-[20px] flex items-center gap-3 transition-all ${viewMode === 'MONTH' ? 'bg-[#A1AED1] text-[#47510B]' : 'text-white/40 hover:text-white'}`}
          >
            <LayoutGrid size={24} /> <span className="text-xl">MONTHLY</span>
          </button>
        </div>

        {/* SELECTORS ENGINE */}
        <div className="flex-grow bg-[#FFF24D] border-[6px] border-[#47510B] rounded-[30px] p-4 flex items-center justify-around gap-4 shadow-[8px_8px_0_0_#47510B]">
          {viewMode === 'DAY' && (
            <div className="relative flex-1">
              <select value={day} onChange={(e) => setDay(e.target.value)} className="w-full appearance-none bg-transparent border-b-4 border-[#47510B] py-2 text-3xl text-[#47510B] outline-none cursor-pointer">
                {[...Array(31)].map((_, i) => <option key={i+1} value={i+1}>{String(i+1).padStart(2, '0')}</option>)}
              </select>
              <ChevronDown className="absolute right-0 top-4 text-[#47510B] pointer-events-none" size={24} />
            </div>
          )}

          <div className="relative flex-[2]">
             <select value={month} onChange={(e) => setMonth(e.target.value)} className="w-full appearance-none bg-transparent border-b-4 border-[#47510B] py-2 text-3xl text-[#47510B] outline-none cursor-pointer">
                {['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'].map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <ChevronDown className="absolute right-0 top-4 text-[#47510B] pointer-events-none" size={24} />
          </div>

          <div className="relative flex-1">
             <select value={year} onChange={(e) => setYear(e.target.value)} className="w-full appearance-none bg-transparent border-b-4 border-[#47510B] py-2 text-3xl text-[#47510B] outline-none cursor-pointer">
                {['2025', '2026', '2027'].map(y => <option key={y} value={y}>{y}</option>)}
             </select>
             <ChevronDown className="absolute right-0 top-4 text-[#47510B] pointer-events-none" size={24} />
          </div>
        </div>
      </div>

      {/* 🌊 DATA DISPLAY: THE LARGE MANIFEST */}
      <div className="flex-grow overflow-y-auto pr-4 custom-scrollbar flex flex-col gap-8 pb-10">
        {scheduleLogs.map((log) => (
          <div key={log.id} className="relative group">
            {/* OFFSET SHADOW */}
            <div className="absolute inset-0 bg-[#47510B] translate-x-3 translate-y-3 rounded-[40px]" />

            <div className="relative bg-white border-[6px] border-[#47510B] rounded-[40px] overflow-hidden flex flex-col xl:flex-row shadow-sm hover:bg-[#FDFAD8] transition-all">

              {/* TIME & DATE BLOCK (BLUE) */}
              <div className="bg-[#A1AED1] border-b-[6px] xl:border-b-0 xl:border-r-[6px] border-[#47510B] p-8 flex flex-col items-center justify-center min-w-[200px]">
                <p className="text-sm font-black text-[#47510B] opacity-50 mb-1">{log.date}</p>
                <h2 className="text-6xl text-[#47510B] leading-none tracking-tighter">{log.time}</h2>
                <div className="mt-4 bg-[#47510B] text-white px-4 py-1 rounded-full text-xs">ID_{log.id}</div>
              </div>

              {/* MAIN CONTENT BLOCK */}
              <div className="flex-grow p-8 flex flex-col justify-center gap-6">
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <MapPin size={24} className="text-[#AB1717]" />
                    <span className="text-xl text-[#AB1717] tracking-[0.2em]">{log.zone} // {log.code}</span>
                  </div>
                  <h1 className="text-7xl text-[#47510B] leading-none">{log.area}</h1>
                </div>

                {/* INFO PILLS (RESIZED FOR INSTANT VIEWING) */}
                <div className="flex flex-wrap gap-6 mt-2">
                   <div className="bg-[#47510B] text-white p-4 rounded-2xl flex items-center gap-4 flex-grow border-4 border-white shadow-[4px_4px_0_0_#47510B]">
                      <User size={32} className="text-[#FFB6A9]" />
                      <div>
                        <p className="text-[10px] opacity-50 leading-none">OPERATOR</p>
                        <p className="text-2xl">{log.worker}</p>
                      </div>
                   </div>
                   <div className="bg-[#FFF24D] border-[4px] border-[#47510B] p-4 rounded-2xl flex items-center gap-4 flex-grow shadow-[4px_4px_0_0_#47510B]">
                      <div className="text-3xl font-black text-[#47510B]">#</div>
                      <div>
                        <p className="text-[10px] opacity-50 leading-none">BIN_NODES</p>
                        <p className="text-2xl">{log.bins}</p>
                      </div>
                   </div>
                </div>
              </div>

              {/* REPORT STATUS (LARGE ALERT) */}
              <div className={`p-8 xl:w-48 flex items-center justify-center border-t-[6px] xl:border-t-0 xl:border-l-[6px] border-[#47510B] ${log.report ? 'bg-[#AB1717] text-white animate-pulse' : 'bg-[#CAD23C]/20 text-[#47510B]'}`}>
                {log.report ? (
                  <div className="flex flex-col items-center text-center gap-2">
                    <AlertCircle size={48} />
                    <span className="text-xs font-black underline italic">INCIDENT_LOG</span>
                  </div>
                ) : (
                  <div className="flex flex-col items-center opacity-30">
                    <div className="w-12 h-12 rounded-full border-4 border-[#47510B]" />
                    <span className="text-[10px] mt-2">CLEAR</span>
                  </div>
                )}
              </div>

            </div>
          </div>
        ))}
      </div>

      {/* 🧭 SIMPLIFIED ACTION BAR (NO UNNECESSARY STATS) */}
      <div className="bg-[#47510B] p-6 rounded-[35px] flex flex-col md:flex-row justify-between items-center border-[6px] border-white shadow-[10px_10px_0_0_#A1AED1]">
         <div className="text-white text-2xl tracking-[0.1em] mb-4 md:mb-0">
            VIEWING: <span className="text-[#FFB6A9]">{viewMode === 'DAY' ? `${day} ${month}` : `FULL_${month}_MANIFEST`}</span>
         </div>
         <button className="w-full md:w-auto bg-[#FFF24D] text-[#47510B] px-12 py-4 rounded-full text-xl font-[1000] border-4 border-[#47510B] shadow-[6px_6px_0_0_#47510B] hover:-translate-y-1 transition-transform flex items-center justify-center gap-3">
            <Download size={24} /> DOWNLOAD_MANIFEST.CSV
         </button>
      </div>

    </div>
  );
};

export default CollectionSchedule;
